import{_ as a,o as t,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"API 与实时通信","description":"在 NestJS 中暴露 Agent：REST 资源、SSE 推流、WebSocket 会话、文件上传与 OpenAPI 契约；事件形状与前端消费见 integration。","frontmatter":{"title":"API 与实时通信","description":"在 NestJS 中暴露 Agent：REST 资源、SSE 推流、WebSocket 会话、文件上传与 OpenAPI 契约；事件形状与前端消费见 integration。","outline":[2,3]},"headers":[],"relativePath":"ts-ai/backend/api-realtime/index.md","filePath":"ts-ai/backend/api-realtime/index.md","lastUpdated":1786083160000}'),d={name:"ts-ai/backend/api-realtime/index.md"};function r(i,e,o,l,c,p){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="api-与实时通信" tabindex="-1">API 与实时通信 <a class="header-anchor" href="#api-与实时通信" aria-label="Permalink to &quot;API 与实时通信&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本分组回答：<strong>已装配好的 Agent 如何通过 HTTP 被前端调用、如何流式返回、何时用 WebSocket、文件如何进后端、契约如何与前端共享。</strong> 全部示例以 NestJS Controller / Gateway 为入口，不展开 Vue 组件或浏览器 SSE 解析。</p><p>前置：读完 <a href="/ts-ai/backend/ai-service/">AI 服务架构</a>（至少会注入 <code>AgentFactoryService</code> 与 <code>RequestContextService</code>）。Agent 侧 <code>stream</code> / <code>AbortSignal</code> 语义见 <a href="/ts-ai/agent/runtime/streaming-cancellation-recovery">流式事件、取消与恢复</a>。</p><h2 id="_1-知识地图" tabindex="-1">1. 知识地图 <a class="header-anchor" href="#_1-知识地图" aria-label="Permalink to &quot;1. 知识地图&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rest-agent-api        → POST /threads、POST /runs；DTO、runId、错误模型、幂等键</span></span>
<span class="line"><span>sse-streaming         → @Sse 或手写 ReadableStream；映射 stream/streamEvents；断开 abort</span></span>
<span class="line"><span>websocket-sessions    → Gateway、房间/thread；双向与背压；何时选 WS 而非 SSE</span></span>
<span class="line"><span>file-upload           → multipart、校验、存储、触发 BullMQ 索引任务</span></span>
<span class="line"><span>openapi-contracts     → @nestjs/swagger、共享类型、版本与破坏性变更</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>integration           → 事件契约、前端消费、重连与去重</span></span>
<span class="line"><span>data-tasks            → Thread/Run 表、长任务、幂等恢复</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>读完应能回答</th></tr></thead><tbody><tr><td>1</td><td><a href="/ts-ai/backend/api-realtime/rest-agent-api">REST Agent API</a></td><td>Thread 与 Run 资源怎么设计、runId 从哪来、错误与幂等怎么统一</td></tr><tr><td>2</td><td><a href="/ts-ai/backend/api-realtime/sse-streaming">SSE 流式响应</a></td><td>如何把 Agent 流映射成 SSE、客户端断开如何 abort</td></tr><tr><td>3</td><td><a href="/ts-ai/backend/api-realtime/websocket-sessions">WebSocket 实时会话</a></td><td>房间模型、鉴权、与 SSE 的分工</td></tr><tr><td>4</td><td><a href="/ts-ai/backend/api-realtime/file-upload">文件上传</a></td><td>multipart 接收、校验、存储与异步索引触发</td></tr><tr><td>5</td><td><a href="/ts-ai/backend/api-realtime/openapi-contracts">OpenAPI 与前后端契约</a></td><td>Swagger 文档、类型共享、兼容策略</td></tr></tbody></table><h2 id="_2-跨章所有权" tabindex="-1">2. 跨章所有权 <a class="header-anchor" href="#_2-跨章所有权" aria-label="Permalink to &quot;2. 跨章所有权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>本分组负责</th><th>其他章节负责</th></tr></thead><tbody><tr><td><strong>REST 路由与 DTO</strong></td><td>Controller、<code>ValidationPipe</code>、状态码、幂等键落库</td><td><a href="/ts-ai/backend/data-tasks/thread-run-message-model">Thread、Run 与 Message 数据模型</a> 表结构</td></tr><tr><td><strong>Agent 调用</strong></td><td><code>invoke</code> / <code>stream</code> / <code>streamEvents</code> 接线、<code>runId</code> 绑定</td><td><a href="/ts-ai/agent/runtime/create-agent">createAgent</a>、<a href="/ts-ai/agent/runtime/middleware-guardrails">Middleware</a></td></tr><tr><td><strong>流式传输实现</strong></td><td>Nest <code>@Sse</code>、响应头、<code>AbortSignal</code> 与连接生命周期</td><td><a href="/ts-ai/agent/runtime/streaming-cancellation-recovery">流式事件、取消与恢复</a> Agent 侧 API</td></tr><tr><td><strong>事件 schema 与前端</strong></td><td>仅说明「适配层应输出产品事件」</td><td><a href="/ts-ai/integration/interaction-protocols/">交互协议</a> 事件名、顺序、终态</td></tr><tr><td><strong>上传 UI 与进度展示</strong></td><td>接收文件、返回 <code>fileId</code> / 任务 id</td><td><a href="/ts-ai/integration/vue-nuxt/file-upload-indexing-state">文件上传与索引状态</a></td></tr><tr><td><strong>索引与 RAG 流水线</strong></td><td>入队 <code>index-document</code> 类 Job</td><td><a href="/ts-ai/knowledge/document-processing/ingestion-pipeline">Ingestion Pipeline</a>、<a href="/ts-ai/backend/data-tasks/bullmq-reliable-workers">BullMQ</a></td></tr><tr><td><strong>OpenAPI 类型</strong></td><td>Nest Swagger 装饰器、导出 spec</td><td>前端 <code>openapi-typescript</code> 消费见 integration 各篇</td></tr></tbody></table><h2 id="_3-典型请求路径" tabindex="-1">3. 典型请求路径 <a class="header-anchor" href="#_3-典型请求路径" aria-label="Permalink to &quot;3. 典型请求路径&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser</span></span>
<span class="line"><span>  ├─ POST /v1/threads              → ThreadsController.create</span></span>
<span class="line"><span>  ├─ POST /v1/threads/:id/runs     → RunsController.create（同步或返回 runId）</span></span>
<span class="line"><span>  ├─ GET  /v1/runs/:runId/stream   → RunsController.stream（SSE）</span></span>
<span class="line"><span>  ├─ WS   /ws                      → AgentGateway（房间 = threadId）</span></span>
<span class="line"><span>  └─ POST /v1/files                → FilesController.upload → BullMQ index job</span></span>
<span class="line"><span>           ↓</span></span>
<span class="line"><span>  AgentFactoryService.create(scene)</span></span>
<span class="line"><span>           ↓</span></span>
<span class="line"><span>  agent.invoke / stream / streamEvents（configurable.thread_id = threadId）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>持久化 Run 状态、消息落库与 Worker 可靠性在 <a href="/ts-ai/backend/data-tasks/">数据与任务</a>；本篇地图只标边界。</p><h2 id="_4-选型速查" tabindex="-1">4. 选型速查 <a class="header-anchor" href="#_4-选型速查" aria-label="Permalink to &quot;4. 选型速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>首选</th><th>备选</th></tr></thead><tbody><tr><td>创建会话、提交问题、轮询终态</td><td>REST <code>POST /runs</code></td><td>—</td></tr><tr><td>单向 token / 进度推送到浏览器</td><td>SSE</td><td>WebSocket（需双向时）</td></tr><tr><td>用户打字指示、多人协作、服务端主动 push 非 Run 事件</td><td>WebSocket</td><td>SSE + 额外 REST</td></tr><tr><td>大文件、二进制</td><td><code>multipart</code> REST</td><td>WS 传 base64（不推荐）</td></tr><tr><td>契约与 TS 类型同步</td><td>OpenAPI 3 + codegen</td><td>手写共享 package</td></tr></tbody></table><h2 id="_5-最小自检" tabindex="-1">5. 最小自检 <a class="header-anchor" href="#_5-最小自检" aria-label="Permalink to &quot;5. 最小自检&quot;">​</a></h2><p>进入 <a href="/ts-ai/backend/data-tasks/">数据与任务</a> 前，本地应能：</p><ol><li><code>POST /v1/threads</code> 返回 <code>threadId</code>；同租户重复 <code>Idempotency-Key</code> 不重复建 Thread。</li><li><code>POST /v1/threads/:threadId/runs</code> 返回 <code>runId</code>；非法 <code>threadId</code> 为 <code>404</code>，校验失败为 <code>422</code>。</li><li><code>GET /v1/runs/:runId/stream</code> 在 Agent 执行期间持续输出 SSE；断开连接后 Run 被 abort（日志可见）。</li><li><code>POST /v1/files</code> 拒绝超限 / 非法 MIME，成功返回 <code>fileId</code> 与 <code>processingJobId</code>。</li><li><code>/api/docs</code> 可打开 Swagger；导出的 <code>openapi.json</code> 与 Controller DTO 一致。</li></ol><h2 id="_6-下一步" tabindex="-1">6. 下一步 <a class="header-anchor" href="#_6-下一步" aria-label="Permalink to &quot;6. 下一步&quot;">​</a></h2><p>按上表顺序读完五篇文章，再进入 <strong><a href="/ts-ai/backend/data-tasks/">数据与任务</a></strong> 把 Thread / Run / Message 持久化与 BullMQ 长任务补齐。前端接线读 <strong><a href="/ts-ai/integration/interaction-protocols/">交互协议</a></strong>。</p>`,19)])])}const u=a(d,[["render",r]]);export{b as __pageData,u as default};
